import {customer,APP_ORIGIN,membership} from './membership.js';
const el=(t,c,text)=>{const n=document.createElement(t);if(c)n.className=c;if(text!==undefined)n.textContent=text;return n};
export function emailLogin(panel){
 customer('/api/telegram/info').then(t=>{if(t.enabled&&/^[a-zA-Z0-9_]{5,32}$/.test(t.username)){const a=el('a','ws-outline','Открыть Telegram-бота');a.href='https://t.me/'+t.username;a.target='_blank';a.rel='noopener';panel.append(a)}}).catch(()=>{});
 const origin=location.hostname.endsWith('github.io')?APP_ORIGIN:location.origin;
 if(location.hostname.endsWith('github.io')){const a=el('a','ws-primary','Открыть вход');a.href=APP_ORIGIN+'/login.html';panel.append(a);return}
 const title=el('h2','','Вход по коду'),lead=el('p','','Проверяем доступные способы входа…'),form=el('form','email-login-form'),status=el('p','auth-message');status.role='status';status.id='auth-message';
 const emailLabel=el('label','','Email'),email=el('input');email.type='email';email.name='email';email.autocomplete='email';email.required=true;email.maxLength=254;email.placeholder='name@yandex.ru';email.setAttribute('aria-describedby','auth-message');emailLabel.append(email);const request=el('button','ws-primary','Получить код');request.type='submit';const codeBox=el('div','auth-code-box');codeBox.hidden=true;const codeLabel=el('label','','Код из письма'),code=el('input');code.type='text';code.name='code';code.inputMode='numeric';code.autocomplete='one-time-code';code.pattern='[0-9]{6}';code.maxLength=6;code.setAttribute('aria-describedby','auth-message');codeLabel.append(code);const verify=el('button','ws-primary','Войти'),resend=el('button','ws-outline','Отправить код ещё раз'),change=el('button','ws-text-link','Изменить email');verify.type=resend.type=change.type='button';codeBox.append(codeLabel,verify,resend,change);form.append(emailLabel,request,codeBox,status);const more=el('div','auth-alternatives'),yandex=el('button','ws-outline','Войти через Яндекс ID');yandex.type='button';yandex.hidden=false;request.disabled=true;email.disabled=true;more.append(yandex);const note=el('p','account-note','Код действует 10 минут. Пароль не нужен. При первом входе создаётся бесплатный аккаунт.');panel.append(title,lead,form,more,note);
 if(['owner','admin'].includes(membership().user?.role)){const a=el('a','settings-admin-link','Настроить вход и отправку писем');a.href='/admin/#auth';panel.append(a)}
 let challenge='',busy=false,until=0,timer,options={email:false,yandex:false};
 function lock(value){busy=value;request.disabled=value||!options.email;verify.disabled=value;resend.disabled=value||!options.email||Date.now()<until}
 function cooldown(seconds){until=Date.now()+seconds*1000;clearInterval(timer);const tick=()=>{const remaining=Math.max(0,Math.ceil((until-Date.now())/1000));resend.disabled=busy||remaining>0;resend.textContent=remaining?'Повторить через '+remaining+' с':'Отправить код ещё раз';if(!remaining)clearInterval(timer)};tick();timer=setInterval(tick,1000)}
 async function send(){if(busy||!options.email||!email.reportValidity())return;lock(true);status.textContent='Отправляем письмо…';try{const r=await customer('/api/auth/request-code',{email:email.value.trim()});challenge=r.challengeId;email.readOnly=true;request.hidden=true;codeBox.hidden=false;code.required=true;code.value='';code.focus();status.textContent='Почтовый сервис принял письмо. Введи шестизначный код; проверь также папку «Спам».';cooldown(r.retryAfter||60)}catch(e){status.textContent=e.message}finally{lock(false)}}
 form.onsubmit=e=>{e.preventDefault();if(challenge)check();else send()};request.onclick=undefined;resend.onclick=send;
 change.onclick=()=>{challenge='';code.required=false;codeBox.hidden=true;email.readOnly=false;request.hidden=false;status.textContent='';clearInterval(timer);email.focus()};
 async function check(){if(busy||!code.reportValidity())return;lock(true);status.textContent='Проверяем код…';try{await customer('/api/auth/verify-code',{email:email.value.trim(),code:code.value.trim(),challengeId:challenge});const next=new URLSearchParams(location.search).get('next');if(next==='/admin/')location.href='/admin/';else if(next==='/workspace.html')location.href='/workspace.html';else if(next==='/projects.html')location.href='/projects.html';else location.href='/account.html'}catch(e){status.textContent=e.message}finally{lock(false)}}verify.onclick=check;
 yandex.onclick=()=>{if(options.yandex)location.href=origin+'/api/auth/yandex/start';else status.textContent='Яндекс ID сейчас недоступен. Выбери доступный способ входа.'};
 customer('/api/auth/options').then(o=>{options=o;form.hidden=false;title.textContent='Вход по почте';email.disabled=false;request.disabled=!o.email;yandex.hidden=false;yandex.disabled=!o.yandex;yandex.title=o.yandex?'Войти через Яндекс':'Яндекс ID подключается владельцем';if(o.email){lead.textContent='Введи email — отправим одноразовый код. Яндекс Почта тоже подойдёт.';status.textContent=''}else{lead.textContent='Email или Яндекс Почта — один аккаунт для всех проектов.';status.textContent='Отправка кодов подключается владельцем. Письмо сейчас не отправляется.';note.textContent='Яндекс ID — отдельный способ входа. Для кода на @yandex.ru он не требуется.'}}).catch(e=>status.textContent=e.message);
 const error=new URLSearchParams(location.search).get('auth_error');if(error)status.textContent=error==='email_exists'?'Этот email уже связан с аккаунтом. Войди по коду, затем подключи Яндекс в разделе «Безопасность».':'Вход через Яндекс не завершён. Попробуй ещё раз.';
}
export async function signOut(){await customer('/api/auth/logout',{});location.href=APP_ORIGIN+'/signout-with-chatgpt'}

